### 4. JavaScript: estructura completa

```js
// Estado de la aplicación
let ciudades = [];
const API_KEY = "TU_API_KEY_AQUI";
const API_BASE = "https://api.openweathermap.org/data/2.5/weather";

// ── Persistencia con localStorage ──────────────────

function guardarCiudades() {
    try {
        localStorage.setItem("ciudades", JSON.stringify(ciudades));
    } catch (error) {
        console.warn("Error al guardar:", error.message);
    }
}

function cargarCiudades() {
    try {
        const datos = localStorage.getItem("ciudades");
        return datos ? JSON.parse(datos) : [];
    } catch (error) {
        console.warn("Error al cargar:", error.message);
        return [];
    }
}

// ── API del clima (async/await) ────────────────────

async function buscarClima(ciudad) {
    try {
        const response = await fetch(
            `${API_BASE}?q=${encodeURIComponent(ciudad)}&appid=${API_KEY}&units=metric&lang=es`
        );

        if (!response.ok) {
            if (response.status === 404) {
                throw new Error("Ciudad no encontrada");
            }
            throw new Error(`Error HTTP: ${response.status}`);
        }

        const data = await response.json();
        return {
            nombre: data.name,
            pais: data.sys.country,
            temp: Math.round(data.main.temp),
            humedad: data.main.humidity,
            viento: Math.round(data.wind.speed * 3.6),
            descripcion: data.weather[0].description,
            icono: data.weather[0].icon
        };
    } catch (error) {
        if (error.message === "Ciudad no encontrada") {
            throw error;
        }
        throw new Error("Error de conexión. Verifica tu internet.");
    }
}

// ── Renderizado ────────────────────────────────────

function renderizarClima() {
    const container = document.getElementById("clima-container");
    const contador = document.getElementById("contador");

    if (ciudades.length === 0) {
        container.innerHTML = '<p class="vacio">Busca una ciudad para ver el clima</p>';
        contador.textContent = "";
        return;
    }

    container.innerHTML = ciudades.map((ciudad, index) => `
        <div class="tarjeta-clima" data-index="${index}">
            <button class="btn-eliminar" data-index="${index}">✕</button>
            <h2>${ciudad.nombre}, ${ciudad.pais}</h2>
            <img src="https://openweathermap.org/img/wn/${ciudad.icono}@2x.png" alt="${ciudad.descripcion}">
            <p class="temp">${ciudad.temp}°C</p>
            <p class="desc">${ciudad.descripcion}</p>
            <div class="detalles">
                <span>💧 ${ciudad.humedad}%</span>
                <span>💨 ${ciudad.viento} km/h</span>
            </div>
        </div>
    `).join("");

    contador.textContent = `${ciudades.length} ciudades guardadas`;
}

// ── Eventos ────────────────────────────────────────

document.getElementById("busqueda").addEventListener("submit", async (event) => {
    event.preventDefault();

    const input = document.getElementById("ciudad-input");
    const nombreCiudad = input.value.trim();

    if (!nombreCiudad) return;

    // Verificar si ya existe
    const existe = ciudades.some(
        c => c.nombre.toLowerCase() === nombreCiudad.toLowerCase()
    );
    if (existe) {
        alert("Esta ciudad ya está en la lista");
        return;
    }

    try {
        input.disabled = true;
        const clima = await buscarClima(nombreCiudad);
        ciudades = [...ciudades, clima];
        guardarCiudades();
        renderizarClima();
        input.value = "";
    } catch (error) {
        alert(error.message);
    } finally {
        input.disabled = false;
        input.focus();
    }
});

document.getElementById("clima-container").addEventListener("click", (event) => {
    if (event.target.classList.contains("btn-eliminar")) {
        const index = parseInt(event.target.dataset.index);
        ciudades = ciudades.filter((_, i) => i !== index);
        guardarCiudades();
        renderizarClima();
    }
});

// ── Inicialización ─────────────────────────────────

ciudades = cargarCiudades();
renderizarClima();
```

